    private static boolean hardFailed;
 private static final String OWNER="com.zte.mifavor.views.MFVBatteryViewLayout",ICON="com.zte.mifavor.views.MFVBatteryMeterView",ROOT="com.android.systemui.statusbar.phone.PhoneStatusBarView";
